def rellenar_fechas_reales(apps, schema_editor):
    """
    Los datos de antes quedan con la fecha que los reportes ya les asignaban:
      - abono de compra: el dia (local) en que se registro.
      - abono de gasto: si se creo junto con el gasto (gasto "pagado de una vez") el reporte de
        banco lo contaba en la fecha del gasto, asi que esa es su fecha; un abono posterior al
        gasto toma el dia en que se registro.
      - compra sin fecha de factura: el dia (local) en que se registro (como ya lo asumian los reportes).
    """
    VGAbonoCompra = apps.get_model('varagrill', 'VGAbonoCompra')
    VGAbonoGasto = apps.get_model('varagrill', 'VGAbonoGasto')
    VGCompra = apps.get_model('varagrill', 'VGCompra')

    pendientes = []
    for abono in VGAbonoCompra.objects.all().iterator():
        abono.fecha_abono = timezone.localtime(abono.fecha_pago).date()
        pendientes.append(abono)
        if len(pendientes) >= 500:
            VGAbonoCompra.objects.bulk_update(pendientes, ['fecha_abono'])
            pendientes = []
    if pendientes:
        VGAbonoCompra.objects.bulk_update(pendientes, ['fecha_abono'])

    pendientes = []
    for abono in VGAbonoGasto.objects.select_related('gasto').iterator():
        dia = timezone.localtime(abono.fecha_pago).date()
        if abs((abono.fecha_pago - abono.gasto.fecha_creacion).total_seconds()) <= 60:
            dia = abono.gasto.fecha_gasto
        abono.fecha_abono = dia
        pendientes.append(abono)
        if len(pendientes) >= 500:
            VGAbonoGasto.objects.bulk_update(pendientes, ['fecha_abono'])
            pendientes = []
    if pendientes:
        VGAbonoGasto.objects.bulk_update(pendientes, ['fecha_abono'])

    for compra in VGCompra.objects.filter(fecha_factura__isnull=True).iterator():
        compra.fecha_factura = timezone.localtime(compra.fecha_creacion).date()
        compra.save(update_fields=['fecha_factura'])


